import json
import os

# Find all files containing VAST K=3 configs
artifact_dir = "/home/ubuntu/.agent-ml-research-prod_0510/projects/causal_annot_error_attrib/artifacts"
files_with_vast_k3 = {}

# Check all JSON files
for root, dirs, files in os.walk(artifact_dir):
    for fname in files:
        if fname.endswith(".json"):
            fpath = os.path.join(root, fname)
            try:
                with open(fpath) as f:
                    data = json.load(f)

                # Look for VAST K=3 matrices
                vast_count = 0

                # Check top-level keys
                for key in data:
                    if "vast" in key.lower() and isinstance(data[key], dict):
                        if "confusion_matrix_normalized" in data[key]:
                            cm = data[key]["confusion_matrix_normalized"]
                            if len(cm) == 3 and len(cm[0]) == 3:
                                vast_count += 1

                # Check confusion_matrices section
                if "confusion_matrices" in data:
                    for key in data["confusion_matrices"]:
                        if "vast" in key.lower():
                            cm = data["confusion_matrices"][key]
                            if len(cm) == 3 and len(cm[0]) == 3:
                                vast_count += 1

                # Check source_matrices section
                if "source_matrices" in data:
                    for key in data["source_matrices"]:
                        if "vast" in key.lower():
                            if "C" in data["source_matrices"][key]:
                                cm = data["source_matrices"][key]["C"]
                                if len(cm) == 3 and len(cm[0]) == 3:
                                    vast_count += 1

                if vast_count > 0:
                    rel_path = fpath.replace(artifact_dir + "/", "")
                    files_with_vast_k3[rel_path] = vast_count
            except:
                pass

print("Files containing VAST K=3 (3×3) confusion matrices:\n")
for fpath in sorted(files_with_vast_k3.keys()):
    count = files_with_vast_k3[fpath]
    print(f"  {fpath:50} ({count} configs)")
